package com.ttl.scanner.util

import org.json.JSONObject
import java.net.URI

data class ParsedQrPayload(
    val url: String,
    val installationId: String? = null,
    val code: String? = null,
    val isAddressOnlyUpdate: Boolean = false
)

object QrPayloadParser {

    /**
     * Parses pairing QR codes generated by Issue Slip Manager desktop.
     * Supports:
     * 1. Compact JSON: {"v":1,"url":"https://...","id":"...","code":"123456"}
     * 2. Query param URL: https://192.168.1.100:8443/?code=123456
     * 3. Plain URL: https://...
     */
    fun parse(rawText: String?): ParsedQrPayload? {
        if (rawText.isNullOrBlank()) return null
        val trimmed = rawText.trim()

        // 1. Try Compact JSON
        if (trimmed.startsWith("{") && trimmed.endsWith("}")) {
            try {
                val json = JSONObject(trimmed)
                val url = json.optString("url", "").trim().trimEnd('/')
                if (url.isNotBlank()) {
                    val id = json.optString("id", "").trim().ifEmpty { null }
                    val code = json.optString("code", "").trim().ifEmpty { null }
                    val isAddressOnly = code.isNullOrBlank()
                    return ParsedQrPayload(
                        url = url,
                        installationId = id,
                        code = code,
                        isAddressOnlyUpdate = isAddressOnly
                    )
                }
            } catch (ignored: Exception) {
                // Not valid JSON, fall through
            }
        }

        // 2. Try URI with query parameters (?code=...)
        if (trimmed.startsWith("http://") || trimmed.startsWith("https://")) {
            try {
                val uri = URI(trimmed)
                val cleanUrl = "${uri.scheme}://${uri.authority}".trimEnd('/')
                val query = uri.query
                var code: String? = null

                if (!query.isNullOrBlank()) {
                    val pairs = query.split("&")
                    for (pair in pairs) {
                        val parts = pair.split("=", limit = 2)
                        if (parts.size == 2 && parts[0].equals("code", ignoreCase = true)) {
                            code = parts[1].trim().ifEmpty { null }
                        }
                    }
                }

                return ParsedQrPayload(
                    url = cleanUrl,
                    installationId = null,
                    code = code,
                    isAddressOnlyUpdate = code.isNullOrBlank()
                )
            } catch (ignored: Exception) {
                // Fall through
            }
        }

        return null
    }
}
